import { builtinFormat, formatNumber, isDateFormat } from './number-format';
import { OfficeImportFailure, openPackage, relKind } from './ooxml';
import type { CellAlign, TableBlock, TableCell, TableDoc, TablePage } from './types';
import { child, children, descendants, ownText, type XmlElement } from './xml';

// External xlsx (created by other apps or desktop Excel) -> TableDoc (D-509): placed on the desk to
// be edited with the same table editor, and re-generated by writeXlsx upon saving as before. Each
// worksheet becomes a page, with one table per page (from A1 to the last cell with content, with
// cell positions matching the original): cell values (shared strings, inline strings numbers,
// booleans, errors), merged cells, column widths, horizontal alignment. Numbers retain their
// original values and number formats (stored as numbers and dates), displayed on the table
// formatted as text; formulas retain only their final evaluated result, stored as values upon
// saving (unevaluated ones store the formula string itself). Ignored: fonts, colors, fills, borders
// (no borders drawn on save either), row heights, hidden state, freezes, filters, comments, images
// and charts, data validation, conditional formatting, names. Pure TypeScript, parsed locally, no
// network requests (Invariant 1); results stay local only, never sent to the AI (Invariant 2).

export interface XlsxImport {
  doc: TableDoc;
  /** Number of formula cells (converted to values on save). */
  formulas: number;
}

/** Maximum total cells across the workbook (for the block from A1 to the last cell of each sheet): if exceeded, the editor view and preview cannot render it smoothly and it is treated as too large. */
export const MAX_IMPORT_CELLS = 20000;
/** The page width for writeXlsx is calculated based on this many characters: page width is set accordingly, and column widths are written back verbatim as character counts. */
const PAGE_CHARS = 110;

/** Address like A1 -> row, col (0-indexed); returns null if not a valid address. */
export function cellRef(ref: string): { row: number; col: number } | null {
  const m = /^\$?([A-Z]{1,3})\$?(\d{1,7})$/i.exec(ref.trim());
  if (!m) return null;
  let col = 0;
  for (const ch of m[1]!.toUpperCase()) col = col * 26 + (ch.charCodeAt(0) - 64);
  const row = Number(m[2]) - 1;
  return row >= 0 && col >= 1 ? { row, col: col - 1 } : null;
}

/** Shared strings and inline strings: direct t element, or multiple rich text t segments joined together (ignore phonetic rPh elements). */
function stringItem(si: XmlElement | undefined): string {
  if (!si) return '';
  const t = child(si, 'x:t');
  if (t) return ownText(t);
  return children(si, 'x:r')
    .map((r) => ownText(child(r, 'x:t')))
    .join('');
}

const flag = (v: string | undefined) => v === '1' || v === 'true';

function alignOf(h: string | undefined): CellAlign | undefined {
  if (h === 'center' || h === 'centerContinuous') return 'center';
  if (h === 'right') return 'right';
  if (h === 'left') return 'left';
  return undefined;
}

interface Xf {
  format: string;
  align?: CellAlign;
}

function readStyles(root: XmlElement | undefined): Xf[] {
  const custom = new Map<number, string>();
  for (const f of children(child(root, 'x:numFmts'), 'x:numFmt')) {
    const id = Number(f.attrs.numFmtId);
    if (Number.isFinite(id) && f.attrs.formatCode !== undefined) custom.set(id, f.attrs.formatCode);
  }
  return children(child(root, 'x:cellXfs'), 'x:xf').map((xf) => {
    const id = Number(xf.attrs.numFmtId ?? 0);
    const align = alignOf(child(xf, 'x:alignment')?.attrs.horizontal);
    return {
      format: custom.get(id) ?? builtinFormat(id) ?? 'General',
      ...(align ? { align } : {}),
    };
  });
}

interface Value {
  text: string;
  write: NonNullable<TableCell['write']>;
  align?: CellAlign;
}

interface SheetValues {
  name: string;
  root: XmlElement | undefined;
  values: Map<string, Value>;
  maxRow: number;
  maxCol: number;
}

/**
 * Open the workbook, reading cells with content from each worksheet (chart sheets and dialog
 * sheets have no cells and are ignored). Throws tooLarge if cells with content exceed maxCells;
 * throws OfficeImportFailure if password-protected, not an xlsx, or corrupted.
 */
function readWorkbook(
  data: Uint8Array,
  maxCells: number,
): { sheets: SheetValues[]; formulas: number; date1904: boolean } {
  const pkg = openPackage(data, (name) => /\.(xml|rels)$/i.test(name));
  const main = pkg.main() ?? (pkg.xml('xl/workbook.xml') ? 'xl/workbook.xml' : undefined);
  const workbook = main ? pkg.xml(main) : undefined;
  if (!main || workbook?.name !== 'x:workbook') throw new OfficeImportFailure('notOffice');
  const rels = pkg.rels(main);
  const relOf = (kind: string) =>
    [...rels.values()].find((r) => relKind(r) === kind && !r.external);
  const stringsPart = relOf('sharedStrings')?.target;
  const strings = children(stringsPart ? pkg.xml(stringsPart) : undefined, 'x:si').map(stringItem);
  const stylesPart = relOf('styles')?.target;
  const xfs = readStyles(stylesPart ? pkg.xml(stylesPart) : undefined);
  const date1904 = flag(child(workbook, 'x:workbookPr')?.attrs.date1904);
  let formulas = 0;
  let cells = 0;
  const sheets: SheetValues[] = [];
  for (const sheet of children(child(workbook, 'x:sheets'), 'x:sheet')) {
    const rel = rels.get(sheet.attrs['r:id'] ?? '');
    if (!rel || rel.external || relKind(rel) !== 'worksheet') continue;
    const root = pkg.xml(rel.target);
    if (!root) continue;
    const values = new Map<string, Value>();
    let maxRow = -1;
    let maxCol = -1;
    let row = -1;
    for (const r of children(child(root, 'x:sheetData'), 'x:row')) {
      row = r.attrs.r ? Number(r.attrs.r) - 1 : row + 1;
      if (!Number.isInteger(row) || row < 0) continue;
      let col = -1;
      for (const c of children(r, 'x:c')) {
        const at = c.attrs.r ? cellRef(c.attrs.r) : null;
        col = at ? at.col : col + 1;
        const value = readCell(c, strings, xfs, date1904);
        if (child(c, 'x:f')) formulas++;
        if (!value) continue;
        values.set(`${row},${col}`, value);
        if (++cells > maxCells) throw new OfficeImportFailure('tooLarge');
        maxRow = Math.max(maxRow, row);
        maxCol = Math.max(maxCol, col);
      }
    }
    sheets.push({ name: sheet.attrs.name ?? '', root, values, maxRow, maxCol });
  }
  return { sheets, formulas, date1904 };
}

/** Read an external xlsx. Throws OfficeImportFailure if password-protected, not an xlsx, corrupted, or too large. */
export function importXlsx(data: Uint8Array): XlsxImport {
  const { sheets, formulas } = readWorkbook(data, MAX_IMPORT_CELLS);
  let total = 0;
  const pages: TablePage[] = [];
  for (const { name, root, values, maxRow: lastRow, maxCol: lastCol } of sheets) {
    let maxRow = lastRow;
    let maxCol = lastCol;
    const merges: { row: number; col: number; rows: number; cols: number }[] = [];
    for (const m of children(child(root, 'x:mergeCells'), 'x:mergeCell')) {
      const [a, b] = (m.attrs.ref ?? '').split(':');
      const from = a ? cellRef(a) : null;
      const to = b ? cellRef(b) : from;
      if (!from || !to) continue;
      const top = Math.min(from.row, to.row);
      const left = Math.min(from.col, to.col);
      const rows = Math.abs(to.row - from.row) + 1;
      const cols = Math.abs(to.col - from.col) + 1;
      merges.push({ row: top, col: left, rows, cols });
      maxRow = Math.max(maxRow, top + rows - 1);
      maxCol = Math.max(maxCol, left + cols - 1);
    }
    const rows = Math.max(1, maxRow + 1);
    const cols = Math.max(1, maxCol + 1);
    total += rows * cols;
    if (total > MAX_IMPORT_CELLS) throw new OfficeImportFailure('tooLarge');
    pages.push(sheetPage(name, root, values, merges, rows, cols));
  }
  if (!pages.length) pages.push(sheetPage('Sheet1', undefined, new Map(), [], 1, 1));
  return { doc: { version: 3, scope: 'all', pages }, formulas };
}

/** Value of a single cell (for table import, D-574): visible text; numbers keep their numeric type, date-formatted ones are marked as date (serial numbers converted to 1900 date system). */
export interface XlsxRowCell {
  text: string;
  number?: number;
  date?: boolean;
}

/**
 * Rows of each worksheet (for table import, D-574): from the first row to the last row with
 * content, each row extending to its last cell with content; merged cells only have a value in
 * their top-left cell. Throws tooLarge if cells with content exceed maxCells, or if the row count
 * exceeds maxCells.
 */
export function readXlsxRows(
  data: Uint8Array,
  maxCells: number,
): { name: string; rows: XlsxRowCell[][] }[] {
  const { sheets, date1904 } = readWorkbook(data, maxCells);
  return sheets.map(({ name, values, maxRow }) => {
    if (maxRow + 1 > maxCells) throw new OfficeImportFailure('tooLarge');
    const rows: XlsxRowCell[][] = Array.from({ length: maxRow + 1 }, () => []);
    for (const [key, value] of values) {
      const [r, c] = key.split(',').map(Number) as [number, number];
      const row = rows[r]!;
      while (row.length < c) row.push({ text: '' });
      const cell: XlsxRowCell = { text: value.text };
      if (value.write.kind === 'number') {
        const date = isDateFormat(value.write.format);
        cell.number = date && date1904 ? value.write.value + 1462 : value.write.value;
        if (date) cell.date = true;
      }
      row[c] = cell;
    }
    return { name, rows };
  });
}

function readCell(
  c: XmlElement,
  strings: readonly string[],
  xfs: readonly Xf[],
  date1904: boolean,
): Value | null {
  const type = c.attrs.t ?? 'n';
  const xf = xfs[Number(c.attrs.s ?? 0)] ?? { format: 'General' };
  const v = child(c, 'x:v');
  const raw = v ? ownText(v) : undefined;
  const align = xf.align ? { align: xf.align } : {};
  const text = (s: string): Value => ({ text: s, write: { kind: 'text' }, ...align });
  if (type === 'inlineStr') {
    const s = stringItem(child(c, 'x:is'));
    return s ? text(s) : null;
  }
  if (raw === undefined) {
    // Unevaluated formulas (written by other programs): keep the formula string itself, otherwise the cell would be completely empty.
    const f = ownText(child(c, 'x:f'));
    return f ? text(`=${f}`) : null;
  }
  if (type === 's') {
    const s = strings[Number(raw)] ?? '';
    return s ? text(s) : null;
  }
  if (type === 'str' || type === 'e' || type === 'd') return raw ? text(raw) : null;
  if (type === 'b') return text(raw === '1' || raw === 'true' ? 'TRUE' : 'FALSE');
  const value = Number(raw);
  if (!Number.isFinite(value) || raw.trim() === '') return raw.trim() ? text(raw) : null;
  return {
    text: formatNumber(value, xf.format, date1904),
    write: { kind: 'number', value, format: xf.format },
    ...align,
  };
}

function sheetPage(
  name: string,
  root: XmlElement | undefined,
  values: Map<string, Value>,
  merges: readonly { row: number; col: number; rows: number; cols: number }[],
  rows: number,
  cols: number,
): TablePage {
  // Column widths (characters): specified by <col> elements; columns without them use the worksheet's default column width.
  const format = child(root, 'x:sheetFormatPr');
  // Excel's default column width is 8.43 characters (base width of 8 plus cell padding).
  const fallback =
    Number(format?.attrs.defaultColWidth) || (Number(format?.attrs.baseColWidth) || 8) + 0.43;
  const colWidths = Array.from({ length: cols }, () => fallback);
  for (const c of descendants(child(root, 'x:cols'), 'x:col')) {
    const min = Number(c.attrs.min);
    const max = Number(c.attrs.max);
    const width = Number(c.attrs.width);
    if (!Number.isFinite(min) || !Number.isFinite(max) || !Number.isFinite(width)) continue;
    for (let k = Math.max(1, min); k <= Math.min(max, cols); k++) colWidths[k - 1] = width;
  }
  // Merged cells: the top-left cell spans multiple rows and columns, and covered positions no longer contain cells; overlaps with preceding merged regions are ignored.
  const covered = new Set<string>();
  const spans = new Map<string, { rows: number; cols: number }>();
  for (const m of merges) {
    let clash = false;
    for (let r = m.row; r < m.row + m.rows && !clash; r++)
      for (let c = m.col; c < m.col + m.cols && !clash; c++) clash = covered.has(`${r},${c}`);
    if (clash) continue;
    for (let r = m.row; r < m.row + m.rows; r++)
      for (let c = m.col; c < m.col + m.cols; c++) covered.add(`${r},${c}`);
    spans.set(`${m.row},${m.col}`, { rows: m.rows, cols: m.cols });
  }
  const cells: TableCell[] = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const key = `${r},${c}`;
      const span = spans.get(key);
      if (covered.has(key) && !span) continue;
      const value = values.get(key);
      cells.push({
        row: r,
        col: c,
        rowSpan: span?.rows ?? 1,
        colSpan: span?.cols ?? 1,
        text: value?.text ?? '',
        ...(value?.align ? { align: value.align } : {}),
        ...(value ? { write: value.write } : {}),
      });
    }
  }
  const table: TableBlock = {
    kind: 'table',
    rows,
    col: 0,
    cols,
    cells,
    box: { x: 0, y: 0, width: PAGE_CHARS, height: rows },
    borderless: true,
  };
  return {
    name,
    source: '',
    width: PAGE_CHARS,
    height: rows,
    lineHeight: 1,
    colWidths: colWidths.map((w) => Math.round(w * 100) / 100),
    blocks: [table],
  };
}
